const transformString = (text, changeCase) => {
    let reversedText = text.split('').reverse().join('');

    if(changeCase) {
        reversedText = reversedText.toUpperCase();
    } else {
        reversedText = reversedText.toLowerCase();
    }

    return reversedText.replace(/[aeiou]/gi, '');
}

